    # each cell -> list of line colors covering it; cells covered by >=2 different colors → 0
    lc={}
    for rb,cb,v in bl:
        cr,cc=rb+1,cb+1
        for r in range(H): lc.setdefault((r,cc),[]).append(v)
        for c in range(W): lc.setdefault((cr,c),[]).append(v)
    for (r,c),vs in lc.items():
        s=set(vs)
        if len(s)>1: res[r][c]=0
        elif len(s)==1: res[r][c]=vs[0]
    return res
